// Only tools that no other node covers. Everything else is reachable either
// natively (const-free schemas on the "LINE MCP" node) or through
// send_line_text / send_line_flex, and routing those here would just give the
// model a second, worse way to do the same thing.
const ALLOWED = ['create_rich_menu', 'broadcast_text_message', 'broadcast_flex_message'];

const tool = String($json.tool ?? '').trim();
const userId = String($json.userId ?? '').trim();
const allowBroadcast = $json.allowBroadcast === true || $json.allowBroadcast === 'true';
const raw = $json.argsJson;

if (!ALLOWED.includes(tool)) {
  throw new Error(`Tool "${tool}" is not callable here. This tool only handles: ${ALLOWED.join(', ')}. Use send_line_text for text, send_line_flex for cards, and the LINE MCP tools for profile and rich menu queries.`);
}

// Broadcast reaches every follower and cannot be recalled. The switch lives in
// the workflow, so enabling it is a human action, not a model decision.
if (tool.startsWith('broadcast_') && !allowBroadcast) {
  throw new Error('Broadcasting is disabled. It sends to every follower of the Official Account and cannot be undone. To enable it, set "allowBroadcast" to true in the "LINE settings" node of the parent workflow.');
}

let args;
if (raw && typeof raw === 'object') {
  args = raw;
} else {
  let text = String(raw ?? '').trim();
  text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  if (!text) {
    args = {};
  } else {
    try {
      args = JSON.parse(text);
    } catch (e) {
      throw new Error(`argsJson is not valid JSON (${e.message}). Return the arguments object as raw JSON only - no markdown fence, no trailing comma.`);
    }
  }
}

if (!args || typeof args !== 'object' || Array.isArray(args)) {
  throw new Error('argsJson must be a JSON object holding the tool arguments.');
}

// push_* tools take a recipient; the workflow owns that value, never the model.
if (tool.startsWith('push_')) {
  if (!/^U[0-9a-f]{32}$/.test(userId)) {
    throw new Error(`Invalid LINE userId: "${userId}". Set it in the "LINE settings" node of the parent workflow.`);
  }
  args.userId = userId;
} else {
  // broadcast_* and create_rich_menu have no recipient - drop a stray one.
  delete args.userId;
}

if (tool === 'create_rich_menu') {
  if (!args.chatBarText || !Array.isArray(args.actions)) {
    throw new Error('create_rich_menu needs "chatBarText" (string) and "actions" (array of 1-6 action objects).');
  }
  if (args.actions.length < 1 || args.actions.length > 6) {
    throw new Error(`create_rich_menu accepts 1-6 actions, got ${args.actions.length}.`);
  }
}

if (tool === 'broadcast_text_message' && !args.message) {
  throw new Error('broadcast_text_message needs a "message" object: { "type": "text", "text": "..." }.');
}
if (tool === 'broadcast_flex_message' && !args.message) {
  throw new Error('broadcast_flex_message needs a "message" object: { "type": "flex", "altText": "...", "contents": { "type": "bubble", ... } }.');
}

return { json: { tool, args } };
